    ViewerAgent physics_agent(ViewerAgent agent) const {
        constexpr std::uint32_t block_fly = 0x80000u, control_fly = 0x2000u;
        if (region_flags() & block_fly) {
            agent.controls &= ~control_fly;
            agent.flying = false;
        }
        return agent;
    }
